const landingHtml = (language) => {
  if (language !== 'uk') return BODY_HTML;
  const template = document.createElement('template');
  template.innerHTML = BODY_HTML;
  const walker = document.createTreeWalker(template.content, NodeFilter.SHOW_TEXT);
  let aboutWord = 0;
  let node;
  while ((node = walker.nextNode())) {
    const source = node.nodeValue;
    const key = source.trim().replace(/\s+/g, ' ');
    const translation = key === 'about' ? (aboutWord++ === 0 ? '' : 'і') : LANDING_TEXT_UK[key];
    if (translation !== undefined) node.nodeValue = source.replace(source.trim(), translation);
  }
  template.content.querySelectorAll('[aria-label], [title]').forEach((el) => {
    ['aria-label', 'title'].forEach((attr) => {
      const value = el.getAttribute(attr);
      const normalized = value?.trim().replace(/\s+/g, ' ');
      if (LANDING_TEXT_UK[normalized]) el.setAttribute(attr, LANDING_TEXT_UK[normalized]);
    });
  });
  template.innerHTML = LANDING_UK.reduce((html, [en, uk]) => html.replaceAll(en, uk), template.innerHTML);
  return template.innerHTML;
};

