export default function Landing() {
  const ref = useRef(null);
  const { language } = useLocale();

  useEffect(() => {
    if (ref.current) {
      ref.current.innerHTML = landingHtml(language);
    }
    // In-page anchors (#data, #more-tools) would be read as routes by the
    // hash router, so scroll to the section by hand instead.
    const el = ref.current;
    const onClick = (e) => {
      const a = e.target.closest && e.target.closest('a[href^="#"]');
      if (!a) return;
      const h = a.getAttribute('href');
      if (h.startsWith('#/') || h === '#') return;
      const t = document.getElementById(h.slice(1));
      if (t) { e.preventDefault(); t.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
    };
    el && el.addEventListener('click', onClick);
    return () => { el && el.removeEventListener('click', onClick); };
  }, [language]);

  return <div ref={ref} />;
}
