import React from 'react';

// "Why only N of the catalog's records appear" -- the breakdown computed by
// scripts/make_lag_data.py and stored as data.funnel in lag_data.json.
export default function CoverageFunnel({ data, titleExtra, useTitles, openExtra, useOpen }) {
  const f = data.funnel;
  if (!f) return null;
  const n = (v) => v.toLocaleString();
  const rows = [
    [f.nopub, 'No publication year'],
    [f.noabout, 'No subject dates at all'],
    [f.undated, 'The subject heading has no date, so the data falls back to the publication year as the “subject year”. The delay would always be 0, which says nothing.'],
    [f.open, 'Period is open-ended up to publication, such as “1991–”. Only an upper bound on the delay can be read from these; see the option below.'],
    [f.past, 'Period runs past the publication year, such as “20th century” for a 1998 book (upper bound only)'],
    [f.notopic, 'Has a usable period but belongs to no topic theme (so it is absent from the topic chart)'],
  ];
  const used = f.usable;
  const extra = (useTitles ? titleExtra : 0) + (useOpen ? openExtra : 0);
  return (
    <details className="lag-funnel">
      <summary>
        Why only {n(used + extra)} of {n(data.totalRecords)} records appear
      </summary>
      <table className="lag-table">
        <thead><tr><th>Records</th><th>Why they are not on the chart</th></tr></thead>
        <tbody>
          {rows.map(([c, why]) => <tr key={why}><td>{n(c)}</td><td>{why}</td></tr>)}
          <tr><td><b>{n(used)}</b></td><td><b>A real dated period that ends before publication, in a topic theme. These are used.</b></td></tr>
          <tr><td>+{n(titleExtra)}</td><td>Can be added with “Also use dates found in titles” (year ranges and centuries in the title) {useTitles ? '— currently on' : '— currently off'}</td></tr>
          {openExtra != null && <tr><td>+{n(openExtra)}</td><td>Can be added with “Include open-ended periods” (delay measured from the period's start, so a maximum) {useOpen ? '— currently on' : '— currently off'}</td></tr>}
        </tbody>
      </table>
      <p className="lag-muted">
        The measure needs a period that ended before the book was published, so most of the catalog
        (books about the country in general or about the present) cannot be used. Reading a delay out of
        those records would require a date the catalog does not hold.
      </p>
    </details>
  );
}
