// Corrections to the time index that can be edited on the Time editor page.
// Shape: { books: { "<LCCN>": { d0, d1, open, note } }, gaz: { "<gazetteer id>": { start, end, open } } }
// "open" means "until now": the end year is always the current year.
// Two layers: public/data/manual_overrides.json (the saved file, shared with everyone who uses the site)
// and this browser's own edits (localStorage), which are applied on top and are only seen in this browser until exported.
export const LS_KEY = 'dk508_time_overrides_local';

export async function loadFileOverrides() {
  try {
    const r = await fetch(`${process.env.PUBLIC_URL}/data/manual_overrides.json`, { cache: 'no-store' });
    if (!r.ok) return { books: {}, gaz: {} };
    const j = await r.json();
    return { books: j.books || {}, gaz: j.gaz || {} };
  } catch (e) { return { books: {}, gaz: {} }; }
}

export function loadLocalOverrides() {
  try {
    const j = JSON.parse(localStorage.getItem(LS_KEY) || 'null');
    return j ? { books: j.books || {}, gaz: j.gaz || {} } : { books: {}, gaz: {} };
  } catch (e) { return { books: {}, gaz: {} }; }
}

export function saveLocalOverrides(ov) {
  try { localStorage.setItem(LS_KEY, JSON.stringify(ov)); } catch (e) { /* private window: edits stay on the page only */ }
}

export const mergeOverrides = (a, b) => ({ books: { ...a.books, ...b.books }, gaz: { ...a.gaz, ...b.gaz } });

// Applies overrides to the loaded time_index data in place. Source index 6 = "manual entry".
export function applyOverrides(d, ov) {
  const nowY = new Date().getFullYear();
  const byId = new Map(d.books.map((b, i) => [b[0], i]));
  const gId = new Map(d.gaz.map((g, i) => [g[0], i]));
  Object.entries(ov.gaz || {}).forEach(([id, o]) => {
    const i = gId.get(id); if (i == null) return;
    if (o.start !== '' && o.start != null) d.gaz[i][3] = Number(o.start);
    if (o.open) d.gaz[i][4] = nowY; else if (o.end !== '' && o.end != null) d.gaz[i][4] = Number(o.end);
  });
  Object.entries(ov.books || {}).forEach(([id, o]) => {
    const i = byId.get(id); if (i == null) return;
    const b = d.books[i];
    if (Array.isArray(o.ranges) && o.ranges.length) {
      const now = nowY;
      const ranges = o.ranges.map((r) => {
        const rawStart = r.d0 ?? r.start, rawEnd = r.d1 ?? r.end;
        if (rawStart === '' || rawStart == null || (!r.open && (rawEnd === '' || rawEnd == null))) return null;
        const start = Number(rawStart), end = r.open ? now : Number(rawEnd);
        return Number.isFinite(start) && Number.isFinite(end) && start <= end ? [start, end, 5, r.open ? 1 : 0] : null;
      }).filter(Boolean).sort((a, c) => a[0] - c[0]);
      if (ranges.length) {
        b[3] = Math.min(...ranges.map((r) => r[0]));
        b[4] = Math.max(...ranges.map((r) => r[1]));
        b[5] = 6;
        b[10] = ranges;
      }
      return;
    }
    if (o.d0 !== '' && o.d0 != null) b[3] = Number(o.d0);
    if (o.open) b[4] = nowY; else if (o.d1 !== '' && o.d1 != null) b[4] = Number(o.d1);
    if (b[3] != null && b[4] != null) { b[5] = 6; b[10] = [[b[3], b[4], 5, o.open ? 1 : 0]]; } // a manual date replaces the ranges read by the rules
  });
  return d;
}
