// Why the pages do not all use the same documents: each one needs different
// things from a record. Counts as in PAGE_INFO above.
const COMPARE = [
  ['/map', '7,031', 'assigned subject-date ranges in the temporal map'],
  ['/subjects-3d', '9,110', 'records drawn from the 11,429-record map snapshot after geographic exclusions'],
  ['/topics', '9,502 of 11,846', 'records with a topic theme; publication-year chart excludes 677 undated records'],
  ['/homogeneity', '9,110', 'same document cohort as Subjects 3D; usable comparison terms vary by measure'],
  ['/distinctive-3d', '9,110', 'same located-document cohort; 3D height and colour show locally distinctive headings'],
  ['/catalog-lab', '3,829', 'records naming a place in exactly one regional-comparison group'],
  ['/lag', '2,915', 'a real dated period that ended before publication, and a topic theme'],
  ['/drift-lab', '7,031', 'assigned time ranges, spread continuously across years'],
  ['/tests-lab', '7,031', 'assigned time ranges from Drift Lab; maps show supported heading and place subsets'],
];

const PAGE_NAMES = { '/map': 'Map & network', '/subjects-3d': '3D relief', '/distinctive-3d': 'Distinctive subjects 3D', '/topics': 'Subject themes', '/homogeneity': 'Homogeneity map', '/catalog-lab': 'Language change and Polish influence', '/lag': 'Publication delay', '/drift-lab': 'Spatial and temporal change', '/tests-lab': 'Subject vector tests' };

export default function SiteNav() {
  const [open, setOpen] = useState(false);
  const [showInfo, setShowInfo] = useState(() => { try { return localStorage.getItem('dk508.scope') !== 'hidden'; } catch (e) { return true; } });
  const toggleInfo = () => { const v = !showInfo; setShowInfo(v); try { localStorage.setItem('dk508.scope', v ? 'shown' : 'hidden'); } catch (e) { /* storage unavailable */ } };
  const loc = useLocation();
  const { tr } = useLocale();
  useEffect(() => setOpen(false), [loc.pathname]);
  const info = PAGE_INFO[loc.pathname];
  return (
    <header className={`sn${open ? ' open' : ''}`} role="banner">
      <div className="sn-row">
        <NavLink to="/" className="sn-brand" end>VICOLEX <span>· DK508 · About</span></NavLink>
        <button type="button" className="sn-toggle" aria-expanded={open} onClick={() => setOpen(!open)}>{open ? tr('Close ✕') : tr('All pages ☰')}</button>
        <nav className="sn-body" aria-label="Site pages">
          {SITE_PAGES.map((g, i) => (
            <React.Fragment key={g.group}>
              {i > 0 && <span className="sn-sep" aria-hidden="true" />}
              <span className="sn-group" role="group" aria-label={tr(g.group)}>
                
                {g.items.map((p) => (
                  <NavLink key={p.to} to={p.to} className={({ isActive }) => `sn-link${isActive ? ' active' : ''}`}>{tr(p.label)}</NavLink>
                ))}
              </span>
            </React.Fragment>
          ))}
        </nav>
      </div>
      {info && !showInfo && <div className="sn-info sn-collapsed"><button type="button" className="sn-hide" onClick={toggleInfo}>Which documents are on this page? ▾</button></div>}
      {info && showInfo && (
        <section className="sn-info" aria-label="Documents on this page">
          <div className="sn-head">
            <span className="sn-kicker">{tr('Documents on this page')}</span>
            <button type="button" className="sn-hide" onClick={toggleInfo}>{tr('Hide ▴')}</button>
          </div>
          <div className="sn-grid">
            {info.stat && <div className="sn-stat"><div className="sn-num">{info.stat[0]}</div><div className="sn-cap">{tr(info.stat[1])}</div></div>}
            <p className="sn-scope">{tr(info.scope)}</p>
          </div>
          <div className="sn-foot">
            <details className="sn-cmp">
              <summary>{tr('Why other pages use different numbers')}</summary>
              <p>{tr('Each page needs something different from a record. Counts below come from their respective source snapshots; the latest subject-themes source has 11,846 records, while several map and analysis files still use the 11,429-record snapshot:')}</p>
              <ul>
                {COMPARE.map(([to, n, why]) => (
                  <li key={to} className={to === loc.pathname ? 'here' : ''}><b>{n}</b> <NavLink to={to} className="sn-link">{tr(PAGE_NAMES[to])}</NavLink> <span>{tr(why)}</span></li>
                ))}
              </ul>
              <p>{tr('Many “years” in the catalog are only the publication year, used when a heading has no dated period. Pages that need a real period therefore keep far fewer records than pages that need only a place and a year.')}</p>
            </details>
            <div className="sn-rel"><span className="sn-kicker">{tr('From here')}</span>{info.rel.map(([to, label]) => <NavLink key={to} to={to} className="sn-pill">{tr(label)} →</NavLink>)}</div>
          </div>
        </section>
      )}
    </header>
  );
}
