import React, { useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import './TestsLab.css';
import { shuffled } from './testsLabLogic';
import { Hist, Panel, useAnimator, C, fmt, pct } from './TestsLab';

// Interactive versions of Figure 1 and of the Poland-and-western-Ukraine test. Data: public/data/tests_lab3.json.

const LCOL = { Ukrainian: '#3987e5', Russian: '#d95926', English: '#199e70', Polish: '#c3c2b7', German: '#898781' };

// ---------- 1 · cumulative books by language ---------------------------------
function Cumulative({ data }) {
  const langs = Object.keys(data.cum);
  const [year, setYear] = useState(2025);
  const [log, setLog] = useState(true);
  const [on, setOn] = useState({ Ukrainian: true, Russian: true, English: true, Polish: false, German: false });
  const [playing, setPlaying] = useState(false);
  const anim = useAnimator();
  const years = data.years;
  const cum = useMemo(() => {
    const o = {};
    for (const l of langs) { let s = 0; o[l] = data.cum[l].map((v) => (s += v)); }
    return o;
  }, [data]); // eslint-disable-line
  const play = () => {
    setPlaying(true); setYear(1850);
    let y = 1850;
    anim.loop(() => { y += 1; setYear(y); return y < 2025; }, () => setPlaying(false));
  };
  const idx = year - years[0];
  const w = 700, h = 380, m = { l: 48, r: 16, t: 14, b: 34 };
  const iw = w - m.l - m.r, ih = h - m.t - m.b;
  const x0 = 1850, x1 = 2025;
  const sx = (y) => m.l + ((y - x0) / (x1 - x0)) * iw;
  const ymax = 6000, ymin = 1;
  const sy = (v) => (log
    ? m.t + ih - ((Math.log10(Math.max(v, 1)) - Math.log10(ymin)) / (Math.log10(ymax) - Math.log10(ymin))) * ih
    : m.t + ih - (Math.min(v, ymax) / ymax) * ih);
  const yt = log ? [1, 10, 100, 1000] : [0, 2000, 4000, 6000];
  const path = (l) => years.map((y, i) => (y >= x0 && y <= year ? `${sx(y)},${sy(cum[l][i])}` : null)).filter(Boolean).join(' ');
  const ua = cum.Ukrainian[idx], ru = cum.Russian[idx];
  const cross = useMemo(() => {
    let tie = null, ahead = null;
    for (let i = 0; i < years.length; i++) {
      if (tie == null && cum.Ukrainian[i] >= cum.Russian[i] && cum.Ukrainian[i] > 50) tie = years[i];
      if (ahead == null && cum.Ukrainian[i] > cum.Russian[i] && cum.Ukrainian[i] > 50) ahead = years[i];
    }
    return { tie, ahead };
  }, [cum, years]);
  return (
    <Panel n="1" title="When did each language start to appear, and when did Ukrainian pass Russian?"
      lead="Each line is the running total of books in the catalog by language, counting a book once for each language it lists. Slide the year or press play to watch the collection grow.">
      <div className="tl-toolbar">
        <label className="tl-grow">Year <input type="range" min="1850" max="2025" value={year} onChange={(e) => setYear(+e.target.value)} /> <b>{year}</b></label>
        <label><input type="checkbox" checked={log} onChange={(e) => setLog(e.target.checked)} /> log scale</label>
        <div className="tl-btns"><button onClick={play} disabled={playing}>Play from 1850</button></div>
      </div>
      <div className="tl-toolbar">
        {langs.map((l) => (
          <label key={l}><input type="checkbox" checked={!!on[l]} onChange={(e) => setOn({ ...on, [l]: e.target.checked })} />
            <i style={{ display: 'inline-block', width: 10, height: 10, borderRadius: '50%', background: LCOL[l] }} /> {l}</label>
        ))}
      </div>
      <div className="tl-row">
        <div className="tl-col tl-map">
          <svg viewBox={`0 0 ${w} ${h}`} className="tl-svg" role="img" aria-label="Cumulative books by language">
            {yt.map((v) => <g key={v}><line x1={m.l} x2={w - m.r} y1={sy(v)} y2={sy(v)} className="tl-grid" /><text x={m.l - 6} y={sy(v) + 4} textAnchor="end" className="tl-tick">{v.toLocaleString()}</text></g>)}
            {[1850, 1875, 1900, 1925, 1950, 1975, 2000, 2025].map((y) => <text key={y} x={sx(y)} y={h - 12} textAnchor="middle" className="tl-tick">{y}</text>)}
            {[[1917, 'Republic'], [1921, ''], [1945, 'WWII']].filter((q) => q[1]).map(([y, t]) => <g key={y}><line x1={sx(y)} x2={sx(y)} y1={m.t} y2={m.t + ih} stroke="#3a4048" strokeDasharray="3 4" /><text x={sx(y) + 3} y={m.t + 11} className="tl-tick">{t}</text></g>)}
            {langs.filter((l) => on[l]).map((l) => <polyline key={l} points={path(l)} fill="none" stroke={LCOL[l]} strokeWidth="2.2" />)}
            <line x1={sx(year)} x2={sx(year)} y1={m.t} y2={m.t + ih} stroke={C.white} strokeWidth="1" opacity="0.5" />
          </svg>
        </div>
        <div className="tl-col tl-readout">
          <p>By <b>{year}</b> the catalog holds {langs.map((l) => `${cum[l][idx].toLocaleString()} ${l}`).join(', ')} books.</p>
          <p>Ukrainian {ua > ru ? 'is ahead of' : ua === ru ? 'equals' : 'is behind'} Russian ({ua.toLocaleString()} against {ru.toLocaleString()}). {year < 1850 ? '' : ''}</p>
          <p className="tl-muted">Ukrainian ties Russian in {cross.tie} and is ahead from {cross.ahead}. The first Ukrainian-language books in the catalog date from 1888, and a clear step appears around 1917-1921, during the first republic. The crossover says what the Library of Congress collected, including a lot of diaspora publishing, so it is not evidence about how freely Ukrainian could be printed.</p>
        </div>
      </div>
    </Panel>
  );
}

// ---------- 2 · Poland and the west ---------------------------------------------
function PolandWest({ data }) {
  const P = data.poland;
  const [measure, setMeasure] = useState(2);
  const [era, setEra] = useState('all');
  const [nulls, setNulls] = useState([]);
  const [running, setRunning] = useState(false);
  const anim = useAnimator();
  const rows = useMemo(() => P.rows.filter((r) => era === 'all' || r[1] === era), [P, era]);
  const eras = ['all', '1800-1917', '1917-45', '1945-91', '1991+'];
  const stats = useMemo(() => {
    const out = P.regions.map(() => ({ n: 0, k: 0 }));
    for (const r of rows) { out[r[0]].n += 1; out[r[0]].k += r[measure]; }
    return out;
  }, [rows, P, measure]);
  const diff = (labels) => {
    let kw = 0, nw = 0, ko = 0, no = 0;
    for (let i = 0; i < rows.length; i++) { if (labels[i] === 0) { nw++; kw += rows[i][measure]; } else { no++; ko += rows[i][measure]; } }
    return nw && no ? kw / nw - ko / no : NaN;
  };
  const obs = diff(rows.map((r) => r[0]));
  useEffect(() => { anim.stop(); setRunning(false); setNulls([]); }, [measure, era]); // eslint-disable-line
  const go = (total) => {
    setRunning(true); let done = 0;
    anim.loop(() => {
      const b = [];
      for (let i = 0; i < 20 && done < total; i++, done++) b.push(diff(shuffled(rows.map((r) => r[0]))));
      setNulls((a) => a.concat(b)); return done < total;
    }, () => setRunning(false));
  };
  const n = nulls.length;
  const p = (nulls.filter((v) => v >= obs).length + 1) / (n + 1);
  const xmax = Math.max(0.25, obs * 1.15);
  const label = measure === 2 ? 'written in Polish' : 'with a Poland or Polish subject heading';
  const eligible = rows.length;
  return (
    <Panel n="2" title="Did Poland leave a mark on books about western Ukraine?"
      lead="Take records that name places in exactly one region. Compare the share written in Polish, or given Poland-related headings, in the west against the other regions. Then shuffle the region labels to see how large a gap chance produces.">
      <div className="tl-toolbar">
        <label>Measure <select value={measure} onChange={(e) => setMeasure(+e.target.value)}><option value={2}>Book is in Polish</option><option value={3}>Poland or Polish in headings</option></select></label>
        <label className="tl-grow">Period <select value={era} onChange={(e) => setEra(e.target.value)}>{eras.map((e) => <option key={e} value={e}>{e === 'all' ? 'All periods' : e}</option>)}</select></label>
        <div className="tl-btns">
          <button onClick={() => go(200)} disabled={running || !Number.isFinite(obs)}>Shuffle 200</button>
          <button onClick={() => go(1000)} disabled={running || !Number.isFinite(obs)}>Shuffle 1,000</button>
          <button className="tl-ghost" onClick={() => { anim.stop(); setRunning(false); setNulls([]); }}>Reset</button>
        </div>
      </div>
      <p className="tl-muted"><b>Records shown:</b> {eligible.toLocaleString()} records with a place in exactly one region{era === 'all' ? '' : ` and an assigned period of ${era}`}. Records naming multiple regions or none are excluded.</p>
      <div className="tl-row">
        <div className="tl-col">
          <h3>Share of records {label}, by region</h3>
          <svg viewBox="0 0 520 170" className="tl-hist">
            {stats.map((s, i) => {
              const v = s.n ? s.k / s.n : 0, wd = Math.min(380, v * 1500);
              return (
                <g key={i} transform={`translate(0 ${10 + i * 38})`}>
                  <text x="0" y="17" className="tl-tick">{P.regions[i]}</text>
                  <rect x="62" y="3" width={Math.max(2, wd)} height="22" rx="3" fill={i === 0 ? C.orange : C.grey} />
                  <text x={62 + Math.max(2, wd) + 8} y="19" className="tl-marklabel" fill={C.pale}>{pct(v)} ({s.k}/{s.n})</text>
                </g>
              );
            })}
          </svg>
        </div>
        <div className="tl-col">
          <Hist values={nulls} xmin={-0.05} xmax={xmax} bins={36} height={200} xlabel="gap: west share minus other regions' share"
            marks={Number.isFinite(obs) ? [{ x: obs, color: C.orange, label: `real gap ${pct(obs)}` }] : []} />
          <div className="tl-readout">
            {Number.isFinite(obs)
              ? <p>In the west, {pct(stats[0].k / stats[0].n)} of {stats[0].n} records are {label}, against {pct((rows.length ? (stats.reduce((a, s) => a + s.k, 0) - stats[0].k) / (rows.length - stats[0].n) : NaN))} elsewhere. {n > 0 ? <>After {n} shuffles the largest gap chance gave is <b>{pct(Math.max(...nulls))}</b>; p ≈ <b>{fmt(p)}</b>.</> : 'Press a shuffle button to see what chance gives.'}</p>
              : <p className="tl-muted">This period has too few records in the west or elsewhere to compare.</p>}
            <p className="tl-muted">The paper's counts use a stricter rule (a single western place), so the numbers here are a little different. Polish presence is concentrated in 1800-1917 and the interwar years, when Galicia was under Habsburg and then Polish rule.</p>
          </div>
        </div>
      </div>
    </Panel>
  );
}

export default function CatalogLab() {
  const [data, setData] = useState(null);
  const [error, setError] = useState(null);
  useEffect(() => {
    let off = false;
    fetch(`${process.env.PUBLIC_URL}/data/tests_lab3.json`).then((r) => r.json()).then((d) => { if (!off) setData(d); }).catch((e) => { console.error(e); if (!off) setError(e); });
    return () => { off = true; };
  }, []);
  return (
    <div className="tl-root">
      <p className="tl-back"><Link to="/tests-lab">← Subject vector tests</Link> · <Link to="/drift-lab">Spatial and temporal change</Link></p>
      <h1>Language change and Polish influence over time</h1>
      <p className="tl-sub">Two more parts of the paper that you can try on the real data: the growth of the catalog by language (Figure 1), and the test for a Polish influence on the west. Random draws change each time.</p>
      {error && <p className="tl-err">The data file could not be loaded.</p>}
      {!data && !error && <p className="tl-muted">Loading…</p>}
      {data && <p className="tl-muted"><b>Records shown:</b> {data.cohort.languageChartBooks.toLocaleString()} catalog records appear in the five-language chart through 2025, producing {data.cohort.languageAssignments.toLocaleString()} language-book entries because multilingual books count once per language. The regional comparison reports its own count after period selection.</p>}
      {data && (<><Cumulative data={data} /><PolandWest data={data} /></>)}
    </div>
  );
}
