export function LocaleProvider({ children }) {
  const [language, setLanguage] = useState(() => {
    try { return localStorage.getItem('dk508.language') === 'uk' ? 'uk' : 'en'; } catch (_) { return 'en'; }
  });
  useEffect(() => {
    document.documentElement.lang = language;
    try { localStorage.setItem('dk508.language', language); } catch (_) { /* storage unavailable */ }
  }, [language]);
  const value = useMemo(() => ({ language, setLanguage, tr: (text) => language === 'uk' ? (UK[text] || text) : text }), [language]);
  return <LocaleContext.Provider value={value}>{children}</LocaleContext.Provider>;
}

export function useLocale() { return useContext(LocaleContext); }

// Translate interface text added by React, D3, or the legacy HTML map while
// leaving catalog records untouched. English source strings are retained so
// changing back to EN restores exact punctuation and spacing.
export function LocaleBoundary({ children }) {
  const { language } = useLocale();
  const rootRef = useRef(null), originals = useRef(new WeakMap());
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return undefined;
    const apply = () => {
      const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
      let node;
      while ((node = walker.nextNode())) {
        const parent = node.parentElement;
        if (!parent || parent.closest('a[href*="lccn.loc.gov"], [data-no-translate], .document-title, .book-title, .record-title, .book-record, .doc-title')) continue;
        if (!originals.current.has(node)) originals.current.set(node, node.nodeValue);
        const source = originals.current.get(node), trimmed = source.trim();
        // Legacy chart pages build their HTML from templates with indentation
        // and line breaks. Match a whitespace-normalized key so these complete
        // explanatory text nodes receive the same translations as React text.
        const translationKey = trimmed.replace(/\s+/g, ' ');
        const translated = language === 'uk' ? UK[translationKey] : null;
        const nextValue = translated ? source.replace(trimmed, translated) : (language !== 'uk' ? source : node.nodeValue);
        // Avoid re-writing an already translated node: the observer watches
        // characterData, so repeated identical writes can otherwise retrigger
        // itself continuously and stall navigation/rendering.
        if (node.nodeValue !== nextValue) node.nodeValue = nextValue;
      }
      root.querySelectorAll('input[placeholder], [title], [aria-label]').forEach((el) => {
        if (el.closest('[data-no-translate]')) return;
        ['placeholder', 'title', 'aria-label'].forEach((attr) => {
          if (!el.hasAttribute(attr)) return;
          const dataKey = `data-en-${attr}`;
          if (!el.hasAttribute(dataKey)) el.setAttribute(dataKey, el.getAttribute(attr));
          const original = el.getAttribute(dataKey);
          el.setAttribute(attr, language === 'uk' ? (UK[original] || original) : original);
        });
      });
    };
    apply();
    const observer = new MutationObserver(() => apply());
    observer.observe(root, { subtree: true, childList: true, characterData: true });
    return () => observer.disconnect();
  }, [language]);
  return React.createElement('div', { ref: rootRef, className: 'locale-boundary', style: { display: 'contents' } }, children);
}

export function LanguageSwitch() {
  const { language, setLanguage } = useLocale();
  return <div className="locale-switch" role="group" aria-label="Language">
    <button type="button" aria-pressed={language === 'en'} onClick={() => setLanguage('en')}>EN</button>
    <button type="button" aria-pressed={language === 'uk'} onClick={() => setLanguage('uk')}>УКР</button>
  </div>;
}
