import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import './TestsLab.css';
import OvalMap from './OvalMap';
import {
  spread, sampleIdx, keepRow, percentile,
} from './testsLabLogic';

// Interactive versions of the tests in the paper. Data: public/data/tests_lab.json.

const W = 700, H = 480;
const LAT0 = 52.8, LAT1 = 44.0, LON0 = 22.0, LON1 = 40.6;
const px = (lon) => ((lon - LON0) / (LON1 - LON0)) * W;
const py = (lat) => ((LAT0 - lat) / (LAT0 - LAT1)) * H;
function Shape({ q, shape, color, w }) {
  const cx = px(q.lon0), cy = py(q.lat0);
  if (shape === 'circle') return <circle cx={cx} cy={cy} r={q.circ * KM_PX} fill="none" stroke={color} strokeWidth={w} strokeDasharray="6 4" />;
  return <ellipse cx={cx} cy={cy} rx={q.ra * KM_PX} ry={q.rb * KM_PX} transform={`rotate(${-q.theta} ${cx} ${cy})`} fill="none" stroke={color} strokeWidth={w} strokeDasharray="6 4" />;
}
const KM_PX = W / ((LON1 - LON0) * Math.cos((48 * Math.PI) / 180) * 111.32);
export const C = { blue: '#3987e5', orange: '#d95926', aqua: '#199e70', grey: '#6b6a66', pale: '#c3c2b7', white: '#f2f3f5' };
export const fmt = (x, d = 3) => (x == null || Number.isNaN(x) ? '–' : x.toFixed(d));
export const pct = (x, d = 1) => `${(x * 100).toFixed(d)}%`;

// ---------- shared pieces ---------------------------------------------------
export function Hist({ values, marks = [], xmin, xmax, bins = 30, xlabel, width = 560, height = 220, unit = '' }) {
  const m = { l: 36, r: 14, t: 18, b: 40 };
  const iw = width - m.l - m.r, ih = height - m.t - m.b;
  const sx = (v) => m.l + ((v - xmin) / (xmax - xmin)) * iw;
  const counts = new Array(bins).fill(0);
  for (const v of values) {
    const b = Math.min(bins - 1, Math.max(0, Math.floor(((v - xmin) / (xmax - xmin)) * bins)));
    counts[b] += 1;
  }
  const cmax = Math.max(1, ...counts);
  const ticks = 5;
  return (
    <svg viewBox={`0 0 ${width} ${height}`} className="tl-hist" role="img" aria-label={xlabel}>
      {counts.map((c, i) => {
        const x0 = sx(xmin + (i / bins) * (xmax - xmin)), x1 = sx(xmin + ((i + 1) / bins) * (xmax - xmin));
        const h = (c / cmax) * ih;
        return <rect key={i} x={x0 + 0.5} y={m.t + ih - h} width={Math.max(0, x1 - x0 - 1)} height={h} rx="1.5" fill={C.grey} opacity="0.85" />;
      })}
      <line x1={m.l} x2={width - m.r} y1={m.t + ih} y2={m.t + ih} stroke="#3a4048" />
      {Array.from({ length: ticks + 1 }, (_, i) => {
        const v = xmin + (i / ticks) * (xmax - xmin);
        return (
          <g key={i}>
            <line x1={sx(v)} x2={sx(v)} y1={m.t + ih} y2={m.t + ih + 4} stroke="#3a4048" />
            <text x={sx(v)} y={m.t + ih + 16} textAnchor="middle" className="tl-tick">{Math.abs(xmax) < 2 ? v.toFixed(2) : Math.round(v)}{unit}</text>
          </g>
        );
      })}
      <text x={m.l + iw / 2} y={height - 6} textAnchor="middle" className="tl-axis">{xlabel}</text>
      {marks.map((mk, i) => (
        <g key={i}>
          <line x1={sx(mk.x)} x2={sx(mk.x)} y1={m.t - 4} y2={m.t + ih} stroke={mk.color} strokeWidth="2.2" />
          <text x={Math.min(Math.max(sx(mk.x), m.l + 30), width - m.r - 30)} y={m.t - 6} textAnchor="middle" className="tl-marklabel" fill={mk.color}>{mk.label}</text>
        </g>
      ))}
    </svg>
  );
}

export function Panel({ n, title, children, lead }) {
  return (
    <section className="tl-panel">
      <h2><span className="tl-n">{n}</span> {title}</h2>
      {lead && <p className="tl-lead">{lead}</p>}
      {children}
    </section>
  );
}

export function useAnimator() {
  const timer = useRef(null);
  useEffect(() => () => clearTimeout(timer.current), []);
  return {
    loop(step, done) {
      clearTimeout(timer.current);
      const tick = () => { if (step()) timer.current = setTimeout(tick, 16); else if (done) done(); };
      tick();
    },
    stop() { clearTimeout(timer.current); },
  };
}

const outlinePath = (rings) => (rings || []).map((r) => 'M' + r.map(([la, lo]) => `${px(lo).toFixed(1)},${py(la).toFixed(1)}`).join('L') + 'Z').join('');
const gridLines = () => {
  const out = [];
  for (let lon = 24; lon <= 40; lon += 4) out.push(<line key={`x${lon}`} x1={px(lon)} x2={px(lon)} y1="0" y2={H} className="tl-grid" />);
  for (let lat = 46; lat <= 52; lat += 2) out.push(<line key={`y${lat}`} y1={py(lat)} y2={py(lat)} x1="0" x2={W} className="tl-grid" />);
  for (let lon = 24; lon <= 40; lon += 4) out.push(<text key={`tx${lon}`} x={px(lon) + 3} y={H - 5} className="tl-tick">{lon}°E</text>);
  for (let lat = 46; lat <= 52; lat += 2) out.push(<text key={`ty${lat}`} x="4" y={py(lat) - 3} className="tl-tick">{lat}°N</text>);
  return out;
};

// ---------- 1 · compactness ---------------------------------------------------
const KIND = 'theme'; // the lab works on subject headings (themes), as in the paper
const LEVEL_LABEL = ['All places', 'Non-generic places (as in the paper)', 'Also without region centres'];

function Compactness({ data, kind = KIND }) {
  const [level, setLevel] = useState(1);
  const [cid, setCid] = useState(null);
  const [nulls, setNulls] = useState([]);
  const [sample, setSample] = useState(null);
  const [running, setRunning] = useState(false);
  const [measure, setMeasure] = useState('axes');
  const [nulls2, setNulls2] = useState([]);
  const shape = measure === 'circle' ? 'circle' : 'ellipse';
  const two = measure === 'axes';
  const stat = (q) => (measure === 'circle' ? q.circ : measure === 'elong' ? q.elong : two ? q.ra : q.radius);
  const stat2 = (q) => q.rb;
  const isE = measure === 'elong';
  const unitS = isE ? '' : ' km';
  const fm = (v) => (isE ? v.toFixed(2) : String(Math.round(v)));
  const anim = useAnimator();

  const set = data.compact[kind];
  const pool = useMemo(() => set.pool.filter((p) => keepRow(p[4], level)), [set, level]); // every place once, weighted by its books
  const themeRows = useMemo(() => set.pts.filter((p) => keepRow(p[4], level)), [set, level]);
  const clusters = useMemo(() => {
    const cnt = {};
    for (const p of themeRows) cnt[p[3]] = (cnt[p[3]] || 0) + 1;
    return set.clusters.filter((c) => (cnt[c.id] || 0) >= 6).sort((a, b) => b.n - a.n).map((c) => ({ ...c, rows: cnt[c.id] }));
  }, [themeRows, set]);
  useEffect(() => { if (!clusters.find((c) => c.id === cid)) setCid(clusters.length ? clusters[0].id : null); }, [clusters, cid]);
  useEffect(() => { anim.stop(); setRunning(false); setNulls([]); setNulls2([]); setSample(null); }, [level, cid, measure]); // eslint-disable-line

  const members = useMemo(() => themeRows.filter((p) => p[3] === cid), [themeRows, cid]);
  const obs = useMemo(() => (members.length >= 3 ? spread(members.map((p) => p[0]), members.map((p) => p[1]), members.map((p) => p[2]), kind === 'theme_pub') : null), [members, kind]);
  const k = members.length;

  const draw = () => {
    const ix = sampleIdx(pool.length, k);
    const rows = ix.map((j) => pool[j]);
    const s = spread(rows.map((p) => p[0]), rows.map((p) => p[1]), rows.map((p) => p[2]), kind === 'theme_pub');
    return { rows, s };
  };
  const one = () => {
    const d = draw();
    setSample(d);
    if (d.s) { setNulls((a) => a.concat(stat(d.s))); setNulls2((a) => a.concat(stat2(d.s))); }
  };
  const many = (total) => {
    setRunning(true);
    let done = 0;
    anim.loop(() => {
      const batch = [], batch2 = [];
      let last = null;
      for (let i = 0; i < 12 && done < total; i++, done++) { const d = draw(); last = d; if (d.s) { batch.push(stat(d.s)); batch2.push(stat2(d.s)); } }
      setNulls((a) => a.concat(batch)); setNulls2((a) => a.concat(batch2)); if (last) setSample(last);
      return done < total;
    }, () => setRunning(false));
  };
  const reset = () => { anim.stop(); setRunning(false); setNulls([]); setNulls2([]); setSample(null); };

  const sorted2 = useMemo(() => nulls2.slice().sort((a, b) => a - b), [nulls2]);
  const pTwoOf = (arr, v) => { const n = arr.length; if (!n) return null; const lo = (arr.filter((x) => x <= v).length + 1) / (n + 1), hi = (arr.filter((x) => x >= v).length + 1) / (n + 1); return Math.min(1, 2 * Math.min(lo, hi)); };
  const pctLE = (arr, v) => Math.round((arr.filter((x) => x <= v).length / arr.length) * 100);
  const sorted = useMemo(() => nulls.slice().sort((a, b) => a - b), [nulls]);
  const nn = sorted.length;
  const pc = obs ? (sorted.filter((v) => v <= stat(obs)).length + 1) / (nn + 1) : null;
  const ps = obs ? (sorted.filter((v) => v >= stat(obs)).length + 1) / (nn + 1) : null;
  const pTwo = obs && nn ? Math.min(1, 2 * Math.min(pc, ps)) : null;
  const cl = clusters.find((c) => c.id === cid);
  const xmin = isE ? 1 : 0;
  const xmax = Math.max(isE ? 4 : 500, obs ? stat(obs) * 1.2 : 0, nn ? percentile(sorted, 0.995) * 1.1 : 0);
  const xmax2 = Math.max(250, obs ? obs.rb * 1.2 : 0, nn ? percentile(sorted2, 0.995) * 1.1 : 0);

  return (
    <Panel n="1" title="Is a subject heading more compact than a random set of places?"
      lead="Pick a subject heading, then draw random sets of places with the same number of places. If a subject belonged to one area, its places would sit closer together than random ones.">
      <div className="tl-toolbar">
        <label>Places <select value={level} onChange={(e) => setLevel(+e.target.value)}>{[1, 2].map((i) => <option key={i} value={i}>{LEVEL_LABEL[i]}</option>)}</select></label>
        <label>Measure <select value={measure} onChange={(e) => setMeasure(e.target.value)}><option value="axes">Ellipse: radius 1 (long) and radius 2 (short)</option><option value="radius">Ellipse: one combined radius (as in the paper)</option><option value="elong">Ellipse: elongation (long ÷ short axis)</option><option value="circle">Circle: radius</option></select></label>
        <label className="tl-grow">Subject heading <select value={cid ?? ''} onChange={(e) => setCid(+e.target.value)}>{clusters.map((c) => <option key={c.id} value={c.id}>{c.label} ({c.n} books, {c.rows} places)</option>)}</select></label>
      </div>
      <div className="tl-row">
        <div className="tl-col tl-map">
          <svg viewBox={`0 0 ${W} ${H}`} className="tl-svg">
            {gridLines()}
            <path d={outlinePath(data.outline)} className="tl-outline" />
            {pool.map((p, i) => <circle key={i} cx={px(p[1])} cy={py(p[0])} r={1.8 + Math.sqrt(p[2]) * 0.25} fill={C.grey} opacity="0.25" />)}
            {sample && sample.rows.map((p, i) => <circle key={`s${i}`} cx={px(p[1])} cy={py(p[0])} r={2.6 + Math.sqrt(p[2]) * 0.3} fill={C.orange} opacity="0.75" />)}
            {sample && sample.s && <Shape q={sample.s} shape={shape} color={C.orange} w="2" />}
            {members.map((p, i) => <circle key={`m${i}`} cx={px(p[1])} cy={py(p[0])} r={2.6 + Math.sqrt(p[2]) * 0.3} fill={C.blue} opacity="0.9" />)}
            {obs && <Shape q={obs} shape={shape} color={C.blue} w="2.2" />}
          </svg>
          <div className="tl-legend"><span><i style={{ background: C.blue }} />the subject heading</span><span><i style={{ background: C.orange }} />latest random set</span><span><i style={{ background: C.grey }} />all places</span><span className="tl-muted">dashed {shape === 'circle' ? 'circle = a circle with the same average spread as the oval' : 'ellipse = standard deviational ellipse'}</span></div>
        </div>
        <div className="tl-col">
          <div className="tl-btns">
            <button onClick={one} disabled={running}>Draw 1 random set</button>
            <button onClick={() => many(200)} disabled={running}>Draw 200</button>
            <button onClick={() => many(1000)} disabled={running}>Draw 1,000</button>
            <button className="tl-ghost" onClick={reset}>Reset</button>
          </div>
          <Hist values={sorted} xmin={xmin} xmax={xmax} bins={32} height={two ? 190 : 220} xlabel={isE ? 'elongation of the place set (1 = round)' : measure === 'circle' ? 'circle radius of the place set, km' : two ? 'radius 1: the long radius of the oval, km' : 'combined radius of the place set, km'} unit=""
            marks={obs ? [{ x: stat(obs), color: C.blue, label: `heading ${fm(stat(obs))}${unitS}` }] : []} />
          {two && <Hist values={sorted2} xmin={0} xmax={xmax2} bins={32} height={190} xlabel="radius 2: the short radius of the oval, km" unit=""
            marks={obs ? [{ x: obs.rb, color: C.blue, label: `heading ${Math.round(obs.rb)} km` }] : []} />}
          <div className="tl-readout">
            {cl && obs && (
              <>
                {two ? (
                  <p><b>{cl.label}</b>: {k} places. Radius 1 (long) <b>{Math.round(obs.ra)} km</b>, radius 2 (short) <b>{Math.round(obs.rb)} km</b>, so the oval is {obs.elong.toFixed(1)} times as long as it is wide. Combined radius (the paper's single number) {Math.round(obs.radius)} km.</p>
                ) : (
                  <p><b>{cl.label}</b>: {k} places, {isE ? 'elongation' : measure === 'circle' ? 'circle radius' : 'combined radius'} <b>{fm(stat(obs))}{unitS}</b>{shape === 'ellipse' ? <> (radius 1 {Math.round(obs.ra)} km, radius 2 {Math.round(obs.rb)} km)</> : null}.</p>
                )}
                {nn > 0 ? (two ? (
                  <p>{nn} random sets so far. Radius 1: median <b>{Math.round(percentile(sorted, 0.5))} km</b>, {pctLE(sorted, obs.ra)}% of random sets are as short or shorter, two-sided p ≈ <b>{fmt(pTwoOf(sorted, obs.ra))}</b>. Radius 2: median <b>{Math.round(percentile(sorted2, 0.5))} km</b>, {pctLE(sorted2, obs.rb)}% are as short or shorter, two-sided p ≈ <b>{fmt(pTwoOf(sorted2, obs.rb))}</b>{nn < 200 ? ' (draw more sets for steadier values)' : ''}.</p>
                ) : (
                  <p>{nn} random sets so far, median <b>{fm(percentile(sorted, 0.5))}{unitS}</b>. {pctLE(sorted, stat(obs))}% of random sets are {isE ? 'as round or rounder' : 'as tight or tighter'}. Two-sided p ≈ <b>{fmt(pTwo)}</b>{nn < 200 ? ' (draw more sets for a steadier value)' : ''}.</p>
                )) : <p className="tl-muted">Draw random sets to see where the subject heading falls.</p>}
              </>
            )}
          </div>
        </div>
      </div>
      <p className="tl-note">A subject heading here is one heading term of the catalog (on at least 15 books, with at least six places), plus three groups assembled by hand: the nationalist underground, the Famine of 1932 to 1933 and the German occupation. In the paper this is run for all 101 headings with 1,000 random sets each, and p-values are corrected across headings: none is more compact or more spread out than chance.</p>
    </Panel>
  );
}

// ---------- 2 · which way do the ovals lean? ------------------------------------------
const CITIES = { Moscow: [55.75, 37.62], Warsaw: [52.23, 21.01], Berlin: [52.52, 13.41], Vienna: [48.21, 16.37], Budapest: [47.5, 19.04], Bucharest: [44.43, 26.1], Istanbul: [41.01, 28.98], Minsk: [53.9, 27.57], 'New York': [40.71, -74.01], Toronto: [43.65, -79.38] };
const bearingTo = (la1, lo1, la2, lo2) => {
  const p = Math.PI / 180, y = Math.sin((lo2 - lo1) * p) * Math.cos(la2 * p);
  const x = Math.cos(la1 * p) * Math.sin(la2 * p) - Math.sin(la1 * p) * Math.cos(la2 * p) * Math.cos((lo2 - lo1) * p);
  return ((Math.atan2(y, x) * 180) / Math.PI + 360) % 360;
};
const axisDiff = (a, b) => { const d = Math.abs(a - b) % 180; return Math.min(d, 180 - d); };
function Lean({ data, kind = KIND }) {
  const [level, setLevel] = useState(1);
  const [tA, setTA] = useState(kind === 'theme_pub' ? 'New York' : 'Moscow');
  const [tB, setTB] = useState(kind === 'theme_pub' ? 'Toronto' : 'Warsaw');
  const [tol, setTol] = useState(22.5);
  const [minEl, setMinEl] = useState(1.5);
  const [sel, setSel] = useState(null);
  const set = data.compact[kind];
  const poolAll = useMemo(() => set.pool.filter((p) => keepRow(p[4], level)), [set, level]);
  const rows = useMemo(() => {
    const pool = set.pts.filter((p) => keepRow(p[4], level));
    const by = {};
    for (const p of pool) (by[p[3]] = by[p[3]] || []).push(p);
    const out = [];
    for (const c of set.clusters) {
      const m = by[c.id];
      if (!m || m.length < 6) continue;
      const s = spread(m.map((p) => p[0]), m.map((p) => p[1]), m.map((p) => p[2]), kind === 'theme_pub' ? true : 'auto');
      if (!s) continue;
      out.push({ az: !!s.az, id: c.id, label: c.label, books: c.n, mapped: (level === 1 ? c.m1 : c.m2) ?? null, n: m.length, pts: m, lat: s.latC, lon: s.lonC, elong: s.elong, ra: s.ra, rb: s.rb, lean: (((90 - s.theta) % 180) + 180) % 180 });
    }
    return out;
  }, [set, level, kind]);
  const el = useMemo(() => rows.filter((r) => r.elong >= minEl), [rows, minEl]);
  const classify = (r, lean) => {
    if (kind !== 'theme_pub' && !(r.lat >= 44 && r.lat <= 52.5 && r.lon >= 22 && r.lon <= 40.5)) {
      // centred outside Ukraine: a direction from there says nothing about a neighbour, but an axis that points at the United States or Canada is reported as such
      const dn = Math.min(axisDiff(lean, bearingTo(r.lat, r.lon, ...CITIES['New York'])), axisDiff(lean, bearingTo(r.lat, r.lon, ...CITIES.Toronto)));
      return dn <= tol ? 'North America' : 'outside';
    }
    const da = axisDiff(lean, bearingTo(r.lat, r.lon, ...CITIES[tA])), db = axisDiff(lean, bearingTo(r.lat, r.lon, ...CITIES[tB]));
    if (Math.min(da, db) > tol) return 'neither';
    return da <= db ? tA : tB;
  };
  const obs = useMemo(() => { const c = { [tA]: 0, [tB]: 0, neither: 0, outside: 0, 'North America': 0 }; el.forEach((r) => { c[classify(r, r.lean)] += 1; }); return c; }, [el, tA, tB, tol]); // eslint-disable-line
  useEffect(() => { setSel(null); }, [level]);
  // fair null, as in the paper: random sets of places of the same sizes (not random bearings, which are too easy to beat
  // because Ukraine is wider from east to west than from north to south). Draws are made once per place set and cached.
  const [draws, setDraws] = useState(null);
  useEffect(() => {
    let off = false; const N = 300, out = []; setDraws(null);
    const step = () => {
      if (off) return;
      for (let i = 0; i < 10 && out.length < N; i++) {
        out.push(rows.map((r) => {
          const ix = sampleIdx(poolAll.length, r.n), q = ix.map((j) => poolAll[j]);
          const sp = spread(q.map((p) => p[0]), q.map((p) => p[1]), q.map((p) => p[2]), kind === 'theme_pub' ? true : 'auto');
          return sp ? { lat: sp.latC, lon: sp.lonC, elong: sp.elong, lean: (((90 - sp.theta) % 180) + 180) % 180 } : null;
        }));
      }
      setDraws({ n: out.length, list: out.slice() });
      if (out.length < N) setTimeout(step, 0);
    };
    setTimeout(step, 0);
    return () => { off = true; };
  }, [rows, poolAll]); // eslint-disable-line
  const sims = useMemo(() => {
    if (!draws || draws.n < 20) return null;
    const arrA = [], arrB = [], arrN = [];
    for (const d of draws.list) {
      let a = 0, b = 0, na = 0;
      d.forEach((q) => { if (!q || q.elong < minEl) return; const t = classify(q, q.lean); if (t === tA) a++; else if (t === tB) b++; else if (t === 'North America') na++; });
      arrA.push(a); arrB.push(b); arrN.push(na);
    }
    return { arrA, arrB, arrN, n: draws.n };
  }, [draws, tA, tB, tol, minEl]); // eslint-disable-line
  const mean = (a) => a.reduce((x, y) => x + y, 0) / (a.length || 1);
  const pGE = (a, v) => (a.filter((x) => x >= v).length + 1) / (a.length + 1);
  const nm = data && data.compact.names ? data.compact.names[kind === 'theme_pub' ? 'pub' : 'sub'] : null;
  const nameOf = (la, lo) => (nm && nm[`${la.toFixed(3)},${lo.toFixed(3)}`]) || null;
  const placeFacts = (r) => {
    const list = r.pts.slice().sort((a, b) => b[2] - a[2]);
    const out = [];
    if (r.n <= 12) out.push(`Places and books (${r.n}): ${list.map((p) => `${nameOf(p[0], p[1]) || `${p[0].toFixed(1)}°N ${p[1].toFixed(1)}°E`} ${p[2]}`).join('; ')}.`);
    if (kind === 'theme_pub') {
      const abroad = r.pts.filter((p) => p[1] < -50), home = r.pts.filter((p) => p[1] >= -50);
      if (abroad.length && home.length >= 3) {
        const q = spread(home.map((p) => p[0]), home.map((p) => p[1]), home.map((p) => p[2]), true);
        const ab = abroad.reduce((t, p) => t + p[2], 0), tot = r.pts.reduce((t, p) => t + p[2], 0);
        out.push(`The ${abroad.length} North American place${abroad.length > 1 ? 's' : ''} (${ab} of ${tot} imprints) stretch this oval across the Atlantic. Without them the oval would be centred at ${q.latC.toFixed(1)}°N, ${q.lonC.toFixed(1)}°E, with a combined radius of ${Math.round(q.radius)} km (${Math.round(q.ra)} by ${Math.round(q.rb)} km) instead of ${Math.round(Math.sqrt(r.ra * r.rb))} km. So its length and its lean towards New York or Toronto come from those imprints, not from where the rest were printed.`);
      }
    }
    return out;
  };
  const ovals = useMemo(() => rows.map((r) => {
    const on = r.elong >= minEl, tt = on ? classify(r, r.lean) : 'off';
    return { az: r.az, autoAz: kind !== 'theme_pub', na: tt === 'North America', id: r.id, label: r.label, lat: r.lat, lon: r.lon, ra: r.ra, rb: r.rb, bearing: r.lean, solid: on, color: tt === tA ? C.orange : tt === tB ? C.blue : tt === 'North America' ? '#e0a526' : tt === 'outside' ? '#a78bfa' : C.pale,
      pts: r.pts.map((p) => [p[0], p[1], p[2], nameOf(p[0], p[1])]),
      facts: [`${r.books} books under the heading${r.mapped != null ? `, of which ${r.mapped} name a place that is on the map (${r.n} places in all)` : `, ${r.n} places on the map`}. ${on ? `${tt === 'North America' ? 'Centred outside Ukraine, with its long axis pointing towards the United States and Canada.' : tt === 'outside' ? 'Centred outside Ukraine, so no direction towards a neighbour is counted.' : `Leans towards ${tt === 'neither' ? 'neither city' : tt}.`}` : `Too round (below ${minEl.toFixed(1)}×) to count as having a direction.`}`, ...placeFacts(r)] };
  }), [rows, minEl, tA, tB, tol, nm]); // eslint-disable-line
  const names = Object.keys(CITIES);
  const compass = (b) => ['north', 'north-east', 'east', 'south-east', 'south', 'south-west', 'west', 'north-west'][Math.round(((b % 360) / 45)) % 8];
  return (
    <Panel n="2" title="Which way do the ovals lean?"
      lead="Each oval has a long axis. Here we ask whether the long axes of the subject headings lean towards Moscow or towards the West more often than the ovals of random sets of places of the same sizes would. An axis has two ends, so it can line up with a city at either end. Moscow and Istanbul lie in similar directions seen from Ukraine, so an oval can fall within the window of both; choose Moscow with Istanbul below to assign each oval to the nearer axis. Ovals centred outside Ukraine (headings with many places abroad, such as study and teaching or foreign countries) are shown in purple and not counted, because a direction measured from the Atlantic says nothing about a neighbour. Random draws change every time, so the expected counts move a little between visits.">
      <div className="tl-toolbar">
        <label>Places <select value={level} onChange={(e) => setLevel(+e.target.value)}>{[1, 2].map((i) => <option key={i} value={i}>{LEVEL_LABEL[i]}</option>)}</select></label>
        <label>Compare <select value={tA} onChange={(e) => setTA(e.target.value)}>{names.filter((n) => n !== tB).map((n) => <option key={n}>{n}</option>)}</select>
          {' with '}<select value={tB} onChange={(e) => setTB(e.target.value)}>{names.filter((n) => n !== tA).map((n) => <option key={n}>{n}</option>)}</select></label>
        <label>Tolerance ±{tol}° <input type="range" min="10" max="45" step="2.5" value={tol} onChange={(e) => setTol(+e.target.value)} /></label>
        <label>Only ovals at least {minEl.toFixed(1)}× as long as wide <input type="range" min="1" max="3" step="0.1" value={minEl} onChange={(e) => setMinEl(+e.target.value)} /></label>
      </div>
      <div className="tl-row">
        <div className="tl-map" style={{ flex: '1 1 100%' }}>
          <OvalMap
            ovals={ovals} sel={sel} setSel={setSel} ukraine={data.outline} pool={poolAll} unit="book mentions" fitCities={kind === 'theme_pub' || !!(ovals.find((o) => o.id === sel) || {}).na}
            cities={[...[tA, tB].map((nm, i) => ({ name: nm, lat: CITIES[nm][0], lon: CITIES[nm][1], color: i === 0 ? C.orange : C.blue })), ...(kind !== 'theme_pub' && (ovals.find((o) => o.id === sel) || {}).na ? [{ name: 'New York', lat: CITIES['New York'][0], lon: CITIES['New York'][1], color: '#e0a526' }, { name: 'Toronto', lat: CITIES.Toronto[0], lon: CITIES.Toronto[1], color: '#d96bb0' }] : [])]}
            legend={<><span><i style={{ background: C.orange }} />leans towards {tA}</span><span><i style={{ background: C.blue }} />leans towards {tB}</span>{kind !== 'theme_pub' && <span><i style={{ background: '#e0a526' }} />centred outside Ukraine, towards the United States or Canada</span>}<span><i style={{ background: '#a78bfa' }} />centred outside Ukraine, other direction (not counted)</span><span><i style={{ background: C.pale }} />neither, or not elongated enough (dashed)</span></>} />
          <p className="tl-note">Each oval is drawn at its subject heading's centre with its real radii and lean, on a map of Europe, Turkey and western Russia so that the whole oval is visible. Click an oval or a table row to show only that heading: the map zooms to fit the oval and Ukraine, draws the long axis with its angle from north, and shows the places that made the oval as dots (filled inside the oval, open outside), with the coverage below the map. The dotted lines run from Kyiv to the two cities, so you can see the directions the long axes are compared with. Each oval's lean is measured from its own centre.</p>
        </div>
        <div className="tl-col">
      <div className="tl-readout">
        <p><b>{el.length}</b> of {rows.length} subject headings have an oval that is at least {minEl.toFixed(1)} times as long as wide. Counted as leaning towards {tA}, towards {tB}, or neither, within ±{tol}°:</p>
        {sims && (
          <table className="tl-table">
            <thead><tr><th></th><th>Observed</th><th>Expected by chance</th><th>p (as many or more)</th></tr></thead>
            <tbody>
              <tr><td>towards {tA}</td><td><b>{obs[tA]}</b></td><td>{mean(sims.arrA).toFixed(1)}</td><td>{pGE(sims.arrA, obs[tA]).toFixed(3)}</td></tr>
              <tr><td>towards {tB}</td><td><b>{obs[tB]}</b></td><td>{mean(sims.arrB).toFixed(1)}</td><td>{pGE(sims.arrB, obs[tB]).toFixed(3)}</td></tr>
              <tr><td>neither</td><td>{obs.neither}</td><td></td><td></td></tr>
              {kind !== 'theme_pub' && <tr><td>centred outside Ukraine, axis towards the United States or Canada</td><td><b>{obs['North America']}</b></td><td>{mean(sims.arrN).toFixed(1)}</td><td>{pGE(sims.arrN, obs['North America']).toFixed(3)}</td></tr>}
              <tr><td>centred outside Ukraine, other direction (not counted)</td><td>{obs.outside}</td><td></td><td></td></tr>
            </tbody>
          </table>
        )}
        {sims && <Hist values={sims.arrA} xmin={0} xmax={Math.max(el.length, 1)} bins={Math.min(32, Math.max(el.length, 2))} height={170} xlabel={`number of ovals leaning towards ${tA} in ${sims.n} random sets of places`}
          marks={[{ x: obs[tA], color: C.blue, label: `observed ${obs[tA]}` }]} />}
      </div>
      <div className="tl-tablewrap">
        <table className="tl-table">
          <thead><tr><th>Subject heading</th><th>Books</th><th>Books on map</th><th>Places</th><th>Lean (° from north)</th><th>Long ÷ short</th><th>Off {tA} axis</th><th>Off {tB} axis</th>{kind === 'theme_pub' && <><th>Imprints in North America</th><th>of those: New York / Toronto</th></>}</tr></thead>
          <tbody>
            {rows.slice().sort((a, b) => b.elong - a.elong).map((r) => (
              <tr key={r.id} onClick={() => setSel(sel === r.id ? null : r.id)} style={{ opacity: r.elong >= minEl ? 1 : 0.45, cursor: 'pointer', background: sel === r.id ? '#1f2a38' : undefined }}>
                <td>{r.label}</td><td>{r.books}</td><td>{r.mapped ?? '–'}</td><td>{r.n}</td><td>{Math.round(r.lean)}° ({compass(r.lean)}–{compass(r.lean + 180)})</td><td>{r.elong.toFixed(1)}</td>
                <td>{Math.round(axisDiff(r.lean, bearingTo(r.lat, r.lon, ...CITIES[tA])))}°</td><td>{Math.round(axisDiff(r.lean, bearingTo(r.lat, r.lon, ...CITIES[tB])))}°</td>
                {kind === 'theme_pub' && (() => {
                  const near = (p, la, lo) => Math.hypot((p[0] - la) * 111, (p[1] - lo) * 111 * Math.cos((p[0] * Math.PI) / 180)) < 300;
                  const tot = r.pts.reduce((a, p) => a + p[2], 0) || 1;
                  const na = r.pts.filter((p) => p[1] < -50 && p[0] > 15), nat = na.reduce((a, p) => a + p[2], 0);
                  const ny = na.filter((p) => near(p, 40.71, -74)).reduce((a, p) => a + p[2], 0), to = na.filter((p) => near(p, 43.65, -79.38)).reduce((a, p) => a + p[2], 0);
                  return <><td>{Math.round((100 * nat) / tot)}%</td><td>{nat ? `${Math.round((100 * ny) / nat)}% / ${Math.round((100 * to) / nat)}%` : '–'}</td></>;
                })()}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
        </div>
      </div>
      {kind === 'theme_pub' && <p className="tl-note">Places of publication: these ovals are fitted and drawn on an equidistant map projection (so a long oval across the Atlantic is curved, as a great-circle route is) and here the long axes are compared with New York and Toronto, not with Moscow and Warsaw, and ovals centred outside Ukraine are counted too, because a direction from Europe towards North America is meaningful for imprints. Most ovals are long and run almost east–west because a few imprints in New York, Toronto and other North American cities sit far from the European cluster. The last two columns show how much of each heading's imprints are in North America and how that splits between New York and Toronto (places within 300 km). New York and Toronto lie in nearly the same direction from Europe, so many ovals fall within the window of both; compare them with random place sets of the same sizes before reading anything into a difference. When you click a heading with few places, the panel lists its places with their book counts. For publication ovals it also shows what the oval would look like without the imprints in North America: a few imprints in Cambridge (Mass.), Ottawa or New York can stretch an oval of European imprints across the Atlantic, and then its direction says where those few books were printed, not where the heading's books were printed in general.</p>}
      <p className="tl-note">Direction is measured from each heading's own centre, and the comparison is with random sets of places of the same sizes. Adding more cities makes almost every oval line up with one of them, because the cities surround Ukraine, so compare two at a time. With Moscow and Warsaw, more headings lean towards Moscow than chance gives, but they are the ones that name Russia, the Soviet Union or Crimea among their places (politics and government, relations, autonomy and independence movements and so on); the Warsaw count is what chance gives or lower. Two cautions. Small headings give unstable ovals: the Moscow excess comes mostly from headings with 6 to 14 places and is not clear among headings with 15 or more places (12 against about 10 expected). And among headings with at least half of their places inside Ukraine the excess is also not clear (10 against about 7), which fits the finding that the pull towards Moscow appears where the subject is Russia itself. Click an oval to see how it compares with random sets of the same number of places.</p>
    </Panel>
  );
}

// ---------- page ----------------------------------------------------------------------
export default function TestsLab() {
  const [data, setData] = useState(null);
  const [error, setError] = useState(null);
  const [kind, setKind] = useState('theme');
  const [weighting, setWeighting] = useState('count');
  const [useBinsRaw, setUseBins] = useState(null);
  const useBins = useMemo(() => useBinsRaw || (data && data.compact.bins ? data.compact.bins.map(() => true) : []), [useBinsRaw, data]);
  useEffect(() => {
    let off = false;
    fetch(`${process.env.PUBLIC_URL}/data/tests_lab.json`).then((r) => r.json()).then((d) => { if (!off) setData(d); }).catch((e) => { console.error(e); if (!off) setError(e); });
    return () => { off = true; };
  }, []);
  const dataW = useMemo(() => {
    if (!data) return null;
    const allBins = !data.compact.bins || useBins.every(Boolean);
    if (allBins && weighting === 'count') return data;
    const sel = (arr) => (arr || []).reduce((t, v, k) => t + (!data.compact.bins || useBins[k] ? v : 0), 0);
    const wt = (rows) => rows.map((p) => {
      const n = sel(p[5]);
      const w = weighting === 'equal' ? (n > 0 ? 1 : 0) : weighting === 'new' ? sel(p[6]) : weighting === 'old' ? sel(p[7]) : n;
      return [p[0], p[1], w, p[3], p[4]];
    }).filter((p) => p[2] > 0);
    const comp = { ...data.compact };
    for (const key of ['theme', 'theme_pub']) if (comp[key]) comp[key] = { ...comp[key], pts: wt(comp[key].pts), pool: wt(comp[key].pool) };
    return { ...data, compact: comp };
  }, [data, useBins, weighting]);
  return (
    <div className="tl-root">
      <p className="tl-back"><Link to="/drift-lab">Spatial and temporal change →</Link> · <Link to="/catalog-lab">Language change and Polish influence →</Link> · <Link to="/homogeneity">Homogeneity map →</Link></p>
      <h1>Subject vector tests</h1>
      <p className="tl-sub">The paper asks whether the literature on Ukraine in the DK508 catalog splits into regions. These tests compare subject vectors across places and periods. The map-based tests use assigned date ranges from the spatial and temporal change dataset; each range is apportioned across the historical bands it overlaps. Every panel runs a test on the real data in your browser. Random draws change each time, so p-values may move slightly between runs.</p>
      {data && data.cohort && <p className="tl-muted"><b>Records shown:</b> {data.cohort.assignedDocuments.toLocaleString()} with assigned time ranges; {data.cohort.withSupportedHeading.toLocaleString()} match a heading in the map's supported set, {data.cohort.withSubjectPlace.toLocaleString()} have a subject-place coordinate, and {data.cohort.withPublicationPlace.toLocaleString()} have a publication-place coordinate.</p>}
      {error && <p className="tl-err">The data file could not be loaded.</p>}
      {!data && !error && <p className="tl-muted">Loading…</p>}
      {data && data.compact.bins && (
        <div className="tl-toolbar" style={{ margin: '10px 0', flexWrap: 'wrap' }}>
          <label>Build the ovals from <select value={weighting} onChange={(e) => setWeighting(e.target.value)}>
            <option value="count">the number of books naming each place (as in the paper)</option>
            <option value="equal">each place once, whatever the number of books</option>
            <option value="new">years of publication: newer books count more</option>
            <option value="old">age of publication: older books count more</option>
          </select></label>
          <span className="tl-muted">{weighting === 'new' ? 'Each book counts as its year of publication minus 1800, so a book from 2010 counts about 1.6 times a book from 1920 and a book from 1850 counts very little.' : weighting === 'old' ? 'Each book counts as its age in 2026 (2026 minus its year of publication), so a book from 1920 counts about 5 times a book from 2010.' : weighting === 'equal' ? 'Every place counts the same, so a place named by one book matters as much as Kyiv.' : 'Each place is weighted by the number of books that name it.'}{weighting === 'new' || weighting === 'old' ? ' Books without a year of publication are left out.' : ''}</span>
        </div>
      )}
      {data && data.compact.bins && (
        <div className="tl-toolbar" style={{ margin: '10px 0', flexWrap: 'wrap' }}>
          <span>Count only books about the period:</span>
          {data.compact.bins.map((b, i) => (
            <label key={b} style={{ marginRight: 8 }}><input type="checkbox" checked={useBins[i]} onChange={() => setUseBins(useBins.map((v, j) => (j === i ? !v : v)))} /> {b}</label>
          ))}
          <span className="tl-muted">{useBins.every(Boolean) ? 'All 7,031 books with an assigned time range (the default).' : 'Dates come from the Drift Lab time matrix, not publication years. A date range is divided fractionally across the selected historical bands according to how many years overlap each band. Books without an assigned time range are outside this map. The heading and place counts below reflect this assigned-range cohort.'}</span>
        </div>
      )}
      {data && data.compact.theme_pub && (
        <div className="tl-toolbar" style={{ margin: '10px 0' }}>
          <label>Which places? <select value={kind} onChange={(e) => setKind(e.target.value)}>
            <option value="theme">Places the books are about (subject places)</option>
            <option value="theme_pub">Places where the books were published</option>
          </select></label>
          <span className="tl-muted">{kind === 'theme_pub' ? 'Publication places come from the imprint, not from the subject headings. The count of records with a mappable publication place is shown above; the two kinds of place are never mixed.' : 'Subject places come from the headings and the catalog notes.'}</span>
        </div>
      )}
      {dataW && (<><Compactness data={dataW} kind={kind} key={`c${kind}`} /><Lean data={dataW} kind={kind} key={`l${kind}`} /></>)}
    </div>
  );
}
